<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/mail_service.php';require_once dirname(__DIR__).'/private/mail_engine.php';require_once dirname(__DIR__).'/private/ui.php';
$id=(int)($_GET['id']??0);$folder=(string)($_GET['folder']??'INBOX');$back='mail.php?folder='.rawurlencode($folder).($id?'&id='.$id:'');
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$action=(string)($_POST['action']??'');
 if($action==='sync'){$r=gszMailSync($pdo,gszMailRemote($config),$folder,(int)$config['mail_sync_limit']);$_SESSION['app_notice']='Synchronisiert: '.$r['created'].' neue Nachrichten.'.($r['limited']?' Weitere Nachrichten vorhanden: erneut synchronisieren.':'');}
 elseif(in_array($action,['seen','unseen','move'],true)){gszMailRemoteAction($pdo,gszMailRemote($config),(int)$_SESSION['admin_id'],$id,$action,(string)($_POST['target']??''));$_SESSION['app_notice']=$action==='move'?'Verschiebung vom Server bestätigt; kein endgültiges Expunge ausgeführt.':'Gelesenstatus bestätigt.';}
 elseif($action==='classify'){$pdo->prepare('UPDATE mail_messages SET important=?,answered=? WHERE id=?')->execute([isset($_POST['important'])?1:0,isset($_POST['answered'])?1:0,$id]);gszAudit($pdo,(int)$_SESSION['admin_id'],'mail_classification',['message_id'=>$id]);}
 elseif($action==='assign'){$values=[];foreach(['property_id'=>'properties','customer_id'=>'customers','task_id'=>'tasks','invoice_id'=>'invoices'] as $field=>$table){$value=(int)($_POST[$field]??0);if($value){$q=$pdo->prepare('SELECT id FROM '.$table.' WHERE id=?');$q->execute([$value]);if(!$q->fetchColumn())throw new InvalidArgumentException('Zuordnung nicht gefunden.');}$values[]=$value?:null;}$pdo->prepare('UPDATE mail_messages SET property_id=?,customer_id=?,task_id=?,invoice_id=? WHERE id=?')->execute([...$values,$id]);gszAudit($pdo,(int)$_SESSION['admin_id'],'mail_assignment',['message_id'=>$id]);}
 elseif($action==='rule'){$pattern=trim((string)($_POST['pattern']??''));if($pattern===''||mb_strlen($pattern)>190)throw new InvalidArgumentException('Absenderregel 1–190 Zeichen.');$pdo->prepare('INSERT INTO mail_rules(sender_pattern,important) VALUES(?,?)')->execute([$pattern,isset($_POST['important'])?1:0]);}
 elseif($action==='rule_toggle')$pdo->prepare('UPDATE mail_rules SET active=1-active WHERE id=?')->execute([(int)($_POST['rule_id']??0)]);
 else throw new InvalidArgumentException('Mailaktion unbekannt.');
 }catch(Throwable $e){gszUiError($e);}redirect($back);}
$folders=[];$messages=[];$detail=null;$attachments=[];$ready=true;$rules=[];$page=max(1,min(10000,(int)($_GET['page']??1)));$search=mb_substr(trim((string)($_GET['q']??'')),0,100);$total=0;
try{$folders=$pdo->query('SELECT * FROM mail_folders ORDER BY name')->fetchAll();$rules=$pdo->query('SELECT * FROM mail_rules ORDER BY id')->fetchAll();if($id){$detail=gszMailMessage($pdo,$id);$q=$pdo->prepare('SELECT * FROM mail_attachments WHERE message_id=? ORDER BY id');$q->execute([$id]);$attachments=$q->fetchAll();}else{$where=' FROM mail_messages m JOIN mail_folders f ON f.id=m.folder_id WHERE f.name=? AND m.active=1 AND (m.subject LIKE ? OR m.sender LIKE ? OR m.body LIKE ?)';$args=[$folder,'%'.$search.'%','%'.$search.'%','%'.$search.'%'];$q=$pdo->prepare('SELECT COUNT(*)'.$where);$q->execute($args);$total=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT m.*'.$where.' ORDER BY COALESCE(m.sent_at,m.created_at) DESC,m.id DESC LIMIT 30 OFFSET '.(($page-1)*30));$q->execute($args);$messages=$q->fetchAll();}}catch(Throwable $e){$ready=false;$_SESSION['app_error']='Mail-Datenmodell nicht bereit. Gesamtstand-Migration ausführen.';}
gszPageStart('E-Mail');$connected=filter_var($config['mail_enabled']??false,FILTER_VALIDATE_BOOLEAN)&&!empty($config['mail_host'])&&(function_exists('imap_open')||is_file(dirname(__DIR__).'/private/vendor/imapengine/vendor/autoload.php'));
?><p><?=$connected?'IMAP konfiguriert; Verbindung erst durch ausdrücklichen Synchronisationsauftrag.':'Nicht verbunden. Lokale Nachrichten und Entwürfe bleiben zugänglich.'?> Keine automatische Kategoriesortierung. Nachrichten erscheinen erst nach Synchronisation; Suche und Seiten beziehen sich auf den lokalen Bestand. Keine Remote-Bilder, kein Tracking und kein aktives Mail-HTML.</p><p><a href="compose.php">Neue E-Mail / Entwürfe / Versandstand</a></p>
<?php if($ready):?><nav class="actions"><a href="mail.php?folder=INBOX">Posteingang</a><?php foreach($folders as $f):?><a href="mail.php?folder=<?=e(rawurlencode($f['name']))?>"><?=e($f['name'])?></a><?php endforeach?></nav><form method="post"><?php gszFields('sync');?><button>Ordner ausdrücklich synchronisieren</button></form><?php foreach($folders as $f):if($f['name']!==$folder)continue;?><p>Letzte Synchronisation (UTC): <?=e($f['last_sync']??'nie')?> · letzter UID <?=(int)$f['last_uid']?> · <?=e($f['last_error'])?></p><?php endforeach?>
<?php if($detail):?><section class="card"><h2><?=e($detail['subject'])?></h2><p><?=e($detail['sender'])?> → <?=e($detail['recipients'])?> · <?=e($detail['sent_at']??'Datum unbekannt')?> UTC · <?=$detail['active']?'aktuell':'historischer/verschobener Cacheeintrag'?></p><div style="white-space:pre-wrap;overflow-wrap:anywhere"><?=e($detail['body'])?></div><p><?php foreach(['reply'=>'Antworten','reply_all'=>'Allen antworten','forward'=>'Weiterleiten'] as $mode=>$label):?><a href="compose.php?message=<?=$id?>&amp;mode=<?=e($mode)?>"><?=e($label)?></a> · <?php endforeach?></p>
<?php foreach($attachments as $a):?><p><a href="mail_download.php?id=<?=(int)$a['id']?>">Anhang herunterladen: <?=e($a['original_name'])?></a> · <?=(int)$a['size_bytes']?> Bytes · <a href="accounting.php?mail_attachment=<?=(int)$a['id']?>">Als Belegentwurf prüfen</a></p><?php endforeach?><p>Anhänge werden als Download erzwungen, nicht ausgeführt; kein Virenscan zugesagt.</p>
<form method="post"><?php gszFields($detail['seen']?'unseen':'seen');?><button><?=$detail['seen']?'Als ungelesen markieren':'Als gelesen markieren'?></button></form><form method="post"><?php gszFields('move');?><label>Zielordner (Archiv/Papierkorb entsprechend Server)<select name="target"><?php foreach($folders as $f):?><option><?=e($f['name'])?></option><?php endforeach?></select></label><button>In gewählten Ordner verschieben</button></form>
<form method="post"><?php gszFields('classify');?><label><input type="checkbox" name="important" <?=$detail['important']?'checked':''?>> Wichtig: nach 24 Stunden ohne Antwort erinnern</label><label><input type="checkbox" name="answered" <?=$detail['answered']?'checked':''?>> Antwort erfolgt / Erinnerung erledigt</label><button>Einstufung speichern</button></form><details><summary>Objekt/Kunde/Aufgabe/Rechnung zuordnen</summary><form method="post"><?php gszFields('assign');?><?php foreach(['property_id'=>'Objekt-ID','customer_id'=>'Kunden-ID','task_id'=>'Aufgaben-ID','invoice_id'=>'Rechnungs-ID'] as $field=>$label):?><label><?=e($label)?> (leer = keine)<input type="number" name="<?=e($field)?>" min="1" value="<?=e((string)($detail[$field]??''))?>"></label><?php endforeach?><button>Zuordnung speichern</button></form></details></section>
<?php else:?><form method="get"><input type="hidden" name="folder" value="<?=e($folder)?>"><label>Lokalen Ordner durchsuchen<input name="q" maxlength="100" value="<?=e($search)?>"></label><button>Suchen</button></form><section class="card"><h2><?=e($folder)?> · <?=$total?> Nachrichten</h2><?php foreach($messages as $m):?><article class="task-row"><a href="mail.php?folder=<?=e(rawurlencode($folder))?>&amp;id=<?=(int)$m['id']?>"><?=$m['seen']?'':'● '?><?=e($m['subject'])?></a><p><?=e($m['sender'])?> · <?=e($m['sent_at']??'Datum unbekannt')?> UTC</p></article><?php endforeach?><?php if(!$messages):?><p>Keine synchronisierten Treffer.</p><?php endif?></section><nav class="actions"><?php if($page>1):?><a href="?folder=<?=e(rawurlencode($folder))?>&amp;q=<?=e(rawurlencode($search))?>&amp;page=<?=$page-1?>">Neuere</a><?php endif?><?php if($page*30<$total):?><a href="?folder=<?=e(rawurlencode($folder))?>&amp;q=<?=e(rawurlencode($search))?>&amp;page=<?=$page+1?>">Ältere</a><?php endif?></nav><?php endif?>
<details class="card"><summary>Editierbare Erinnerungsregeln</summary><p>Nur ausdrücklich wichtige Posteingangsmails nach 24h; automatische/bulk/List-Mails ausgeschlossen. Manuelle Einstufung korrigierbar. Regeln wirken auf neu synchronisierte Mails.</p><?php foreach($rules as $r):?><form method="post"><?php gszFields('rule_toggle');?><input type="hidden" name="rule_id" value="<?=(int)$r['id']?>"><p><?=e($r['sender_pattern'])?> · <?=$r['important']?'wichtig':'nicht wichtig'?> · <?=$r['active']?'aktiv':'pausiert'?></p><button>Aktiv/pausiert umstellen</button></form><?php endforeach?><form method="post"><?php gszFields('rule');?><label>Absender enthält<input name="pattern" maxlength="190" required></label><label><input type="checkbox" name="important" checked> Wichtig</label><button>Regel speichern</button></form></details><?php endif?><?php gszPageEnd(); ?>
